inline constexpr std::string_view kContactShadowDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core

in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;

uniform sampler2D texture1;
uniform sampler2D uDepthSampler;
uniform float uContactScalars[7];
uniform vec2 uContactVectors[1];
uniform vec3 uContactDirections[1];
uniform mat4 uContactMatrices[2];

const float kCnaSkyDepth = 0.999;

float cnaDecodeLinearDepth(vec4 channels)
{
    if (uContactScalars[6] < 0.5)
        return channels.r;
    const vec4 shift = vec4(1.0 / 16581375.0, 1.0 / 65025.0, 1.0 / 255.0, 1.0);
    return dot(channels, shift);
}

vec3 cnaViewPositionFromDepth(vec2 uv, float linearDepth)
{
    vec4 clip = vec4(uv * 2.0 - 1.0, 1.0, 1.0);
    vec4 ray = uContactMatrices[1] * clip;
    vec3 direction = ray.xyz / ray.w;
    return direction * (linearDepth / max(-direction.z, 1e-6));
}

vec2 cnaSnapToTexel(vec2 uv)
{
    return (floor(uv * uContactVectors[0]) + 0.5) / uContactVectors[0];
}

bool cnaContactOccluded(float rayViewDepth, float sceneViewDepth,
                        float bias, float thickness)
{
    float difference = rayViewDepth - sceneViewDepth;
    return difference > bias && difference < thickness;
}

void main()
{
    vec4 scene = texture(texture1, TexCoord);
    float centerDepth = cnaDecodeLinearDepth(
        texture(uDepthSampler, cnaSnapToTexel(TexCoord)));
    if (centerDepth <= 0.0 || centerDepth >= kCnaSkyDepth)
    {
        FragColor = scene * SpriteColor;
        return;
    }

    vec3 position = cnaViewPositionFromDepth(TexCoord, centerDepth)
                  * uContactScalars[0];
    float stepLength = uContactScalars[1] / uContactScalars[5];
    float occluded = 0.0;

    for (int i = 1; i <= 64; ++i)
    {
        if (float(i) > uContactScalars[5])
            break;
        vec3 samplePosition = position
                            + uContactDirections[0] * (stepLength * float(i));
        if (samplePosition.z >= -1e-6)
            break;

        vec4 clip = uContactMatrices[0] * vec4(samplePosition, 1.0);
        if (clip.w <= 0.0)
            break;
        vec2 sampleUv = (clip.xy / clip.w) * 0.5 + 0.5;
        if (sampleUv.x < 0.0 || sampleUv.x > 1.0 ||
            sampleUv.y < 0.0 || sampleUv.y > 1.0)
            break;

        float sceneDepth = cnaDecodeLinearDepth(
            textureLod(uDepthSampler, cnaSnapToTexel(sampleUv), 0.0));
        if (sceneDepth <= 0.0 || sceneDepth >= kCnaSkyDepth)
            continue;

        if (cnaContactOccluded(-samplePosition.z, sceneDepth * uContactScalars[0],
                               uContactScalars[3], uContactScalars[2]))
        {
            occluded = 1.0;
            break;
        }
    }

    float visibility = 1.0 - occluded * clamp(uContactScalars[4], 0.0, 1.0);
    FragColor = vec4(scene.rgb * visibility, scene.a) * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kDecalDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core

in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;

uniform sampler2D texture1;
uniform sampler2D uDecalSampler;
uniform sampler2D uNormalSampler;
uniform float uDecalScalars[5];
uniform vec3 uDecalVectors[2];
uniform mat4 uDecalMatrices[2];

float cnaDecodeLinearDepth(vec4 channels)
{
    if (uDecalScalars[4] < 0.5)
        return channels.r;
    const vec4 shift = vec4(1.0 / 16581375.0, 1.0 / 65025.0, 1.0 / 255.0, 1.0);
    return dot(channels, shift);
}

vec3 cnaViewPositionFromDepth(vec2 uv, float linearDepth)
{
    vec4 clip = vec4(uv * 2.0 - 1.0, 1.0, 1.0);
    vec4 ray = uDecalMatrices[0] * clip;
    vec3 direction = ray.xyz / ray.w;
    return direction * (linearDepth / max(-direction.z, 1e-6));
}

void main()
{
    float depth = cnaDecodeLinearDepth(texture(texture1, TexCoord));
    if (depth >= 0.999)
        discard;

    vec3 viewPosition = cnaViewPositionFromDepth(TexCoord, depth)
                      * uDecalScalars[0];
    vec3 local = (uDecalMatrices[1] * vec4(viewPosition, 1.0)).xyz;
    if (any(greaterThan(abs(local), vec3(0.5))))
        discard;

    if (uDecalScalars[3] > 0.5)
    {
        vec3 normal = normalize(texture(uNormalSampler, TexCoord).xyz * 2.0 - 1.0);
        if (dot(normal, -uDecalVectors[0]) < uDecalScalars[2])
            discard;
    }

    vec4 decal = texture(uDecalSampler, local.xy + 0.5);
    FragColor = vec4(decal.rgb * uDecalVectors[1], decal.a * uDecalScalars[1])
              * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kColorGradeInterpolatedStripDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core
in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;
uniform sampler2D texture1;
uniform sampler2D uLutSampler;
uniform vec4 uColorGradeParams;

vec3 cnaLutFetch(ivec3 index)
{
    int slices = int(uColorGradeParams.x);
    return texelFetch(uLutSampler, ivec2(index.z * slices + index.x, index.y), 0).rgb;
}

vec3 cnaLutTrilinear(vec3 colour)
{
    float last = uColorGradeParams.x - 1.0;
    vec3 p = clamp(colour, 0.0, 1.0) * last;
    ivec3 i0 = ivec3(floor(p));
    ivec3 i1 = min(i0 + ivec3(1), ivec3(int(last)));
    vec3 f = p - vec3(i0);
    vec3 c000 = cnaLutFetch(ivec3(i0.x, i0.y, i0.z));
    vec3 c100 = cnaLutFetch(ivec3(i1.x, i0.y, i0.z));
    vec3 c010 = cnaLutFetch(ivec3(i0.x, i1.y, i0.z));
    vec3 c110 = cnaLutFetch(ivec3(i1.x, i1.y, i0.z));
    vec3 c001 = cnaLutFetch(ivec3(i0.x, i0.y, i1.z));
    vec3 c101 = cnaLutFetch(ivec3(i1.x, i0.y, i1.z));
    vec3 c011 = cnaLutFetch(ivec3(i0.x, i1.y, i1.z));
    vec3 c111 = cnaLutFetch(ivec3(i1.x, i1.y, i1.z));
    return mix(mix(mix(c000, c100, f.x), mix(c010, c110, f.x), f.y),
               mix(mix(c001, c101, f.x), mix(c011, c111, f.x), f.y), f.z);
}

vec3 cnaLutTetrahedral(vec3 colour)
{
    float last = uColorGradeParams.x - 1.0;
    vec3 p = clamp(colour, 0.0, 1.0) * last;
    ivec3 i0 = ivec3(floor(p));
    ivec3 i1 = min(i0 + ivec3(1), ivec3(int(last)));
    vec3 f = p - vec3(i0);
    vec3 c000 = cnaLutFetch(ivec3(i0.x, i0.y, i0.z));
    vec3 c111 = cnaLutFetch(ivec3(i1.x, i1.y, i1.z));
    if (f.x > f.y)
    {
        if (f.y > f.z)
        {
            vec3 c100 = cnaLutFetch(ivec3(i1.x, i0.y, i0.z));
            vec3 c110 = cnaLutFetch(ivec3(i1.x, i1.y, i0.z));
            return c000 + f.x * (c100 - c000) + f.y * (c110 - c100)
                        + f.z * (c111 - c110);
        }
        if (f.x > f.z)
        {
            vec3 c100 = cnaLutFetch(ivec3(i1.x, i0.y, i0.z));
            vec3 c101 = cnaLutFetch(ivec3(i1.x, i0.y, i1.z));
            return c000 + f.x * (c100 - c000) + f.z * (c101 - c100)
                        + f.y * (c111 - c101);
        }
        vec3 c001 = cnaLutFetch(ivec3(i0.x, i0.y, i1.z));
        vec3 c101 = cnaLutFetch(ivec3(i1.x, i0.y, i1.z));
        return c000 + f.z * (c001 - c000) + f.x * (c101 - c001)
                    + f.y * (c111 - c101);
    }
    if (f.z > f.y)
    {
        vec3 c001 = cnaLutFetch(ivec3(i0.x, i0.y, i1.z));
        vec3 c011 = cnaLutFetch(ivec3(i0.x, i1.y, i1.z));
        return c000 + f.z * (c001 - c000) + f.y * (c011 - c001)
                    + f.x * (c111 - c011);
    }
    if (f.z > f.x)
    {
        vec3 c010 = cnaLutFetch(ivec3(i0.x, i1.y, i0.z));
        vec3 c011 = cnaLutFetch(ivec3(i0.x, i1.y, i1.z));
        return c000 + f.y * (c010 - c000) + f.z * (c011 - c010)
                    + f.x * (c111 - c011);
    }
    vec3 c010 = cnaLutFetch(ivec3(i0.x, i1.y, i0.z));
    vec3 c110 = cnaLutFetch(ivec3(i1.x, i1.y, i0.z));
    return c000 + f.y * (c010 - c000) + f.x * (c110 - c010)
                + f.z * (c111 - c110);
}

void main()
{
    vec4 source = texture(texture1, TexCoord);
    vec3 colour = clamp(source.rgb, 0.0, 1.0);
    vec3 graded = uColorGradeParams.z >= 0.5
                ? cnaLutTetrahedral(colour) : cnaLutTrilinear(colour);
    FragColor = vec4(mix(source.rgb, graded, uColorGradeParams.y), source.a) * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kColorGradeStripDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core
in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;
uniform sampler2D texture1;
uniform sampler2D uLutSampler;
uniform vec4 uColorGradeParams;

vec3 cnaSampleSlice(vec3 colour, float slice)
{
    float lutSize = uColorGradeParams.x;
    float sliceWidth = 1.0 / lutSize;
    float texelWidth = sliceWidth / lutSize;
    float u = slice * sliceWidth + 0.5 * texelWidth
            + colour.r * texelWidth * (lutSize - 1.0);
    float v = 0.5 / lutSize + colour.g * (lutSize - 1.0) / lutSize;
    return texture(uLutSampler, vec2(u, v)).rgb;
}

void main()
{
    vec4 source = texture(texture1, TexCoord);
    vec3 colour = clamp(source.rgb, 0.0, 1.0);
    float last = uColorGradeParams.x - 1.0;
    float blue = colour.b * last;
    float lower = floor(blue);
    float upper = min(lower + 1.0, last);
    vec3 graded = mix(cnaSampleSlice(colour, lower),
                      cnaSampleSlice(colour, upper),
                      blue - lower);
    FragColor = vec4(mix(source.rgb, graded, uColorGradeParams.y), source.a) * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kColorGradeVolumeDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core
in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;
uniform sampler2D texture1;
uniform sampler3D uLutVolume;
uniform vec4 uColorGradeParams;

vec3 cnaLutFetch(ivec3 index)
{
    return texelFetch(uLutVolume, index, 0).rgb;
}

vec3 cnaLutTrilinear(vec3 colour)
{
    float last = uColorGradeParams.x - 1.0;
    vec3 p = clamp(colour, 0.0, 1.0) * last;
    ivec3 i0 = ivec3(floor(p));
    ivec3 i1 = min(i0 + ivec3(1), ivec3(int(last)));
    vec3 f = p - vec3(i0);
    vec3 c000 = cnaLutFetch(ivec3(i0.x, i0.y, i0.z));
    vec3 c100 = cnaLutFetch(ivec3(i1.x, i0.y, i0.z));
    vec3 c010 = cnaLutFetch(ivec3(i0.x, i1.y, i0.z));
    vec3 c110 = cnaLutFetch(ivec3(i1.x, i1.y, i0.z));
    vec3 c001 = cnaLutFetch(ivec3(i0.x, i0.y, i1.z));
    vec3 c101 = cnaLutFetch(ivec3(i1.x, i0.y, i1.z));
    vec3 c011 = cnaLutFetch(ivec3(i0.x, i1.y, i1.z));
    vec3 c111 = cnaLutFetch(ivec3(i1.x, i1.y, i1.z));
    return mix(mix(mix(c000, c100, f.x), mix(c010, c110, f.x), f.y),
               mix(mix(c001, c101, f.x), mix(c011, c111, f.x), f.y), f.z);
}

vec3 cnaLutTetrahedral(vec3 colour)
{
    float last = uColorGradeParams.x - 1.0;
    vec3 p = clamp(colour, 0.0, 1.0) * last;
    ivec3 i0 = ivec3(floor(p));
    ivec3 i1 = min(i0 + ivec3(1), ivec3(int(last)));
    vec3 f = p - vec3(i0);
    vec3 c000 = cnaLutFetch(ivec3(i0.x, i0.y, i0.z));
    vec3 c111 = cnaLutFetch(ivec3(i1.x, i1.y, i1.z));
    if (f.x > f.y)
    {
        if (f.y > f.z)
        {
            vec3 c100 = cnaLutFetch(ivec3(i1.x, i0.y, i0.z));
            vec3 c110 = cnaLutFetch(ivec3(i1.x, i1.y, i0.z));
            return c000 + f.x * (c100 - c000) + f.y * (c110 - c100)
                        + f.z * (c111 - c110);
        }
        if (f.x > f.z)
        {
            vec3 c100 = cnaLutFetch(ivec3(i1.x, i0.y, i0.z));
            vec3 c101 = cnaLutFetch(ivec3(i1.x, i0.y, i1.z));
            return c000 + f.x * (c100 - c000) + f.z * (c101 - c100)
                        + f.y * (c111 - c101);
        }
        vec3 c001 = cnaLutFetch(ivec3(i0.x, i0.y, i1.z));
        vec3 c101 = cnaLutFetch(ivec3(i1.x, i0.y, i1.z));
        return c000 + f.z * (c001 - c000) + f.x * (c101 - c001)
                    + f.y * (c111 - c101);
    }
    if (f.z > f.y)
    {
        vec3 c001 = cnaLutFetch(ivec3(i0.x, i0.y, i1.z));
        vec3 c011 = cnaLutFetch(ivec3(i0.x, i1.y, i1.z));
        return c000 + f.z * (c001 - c000) + f.y * (c011 - c001)
                    + f.x * (c111 - c011);
    }
    if (f.z > f.x)
    {
        vec3 c010 = cnaLutFetch(ivec3(i0.x, i1.y, i0.z));
        vec3 c011 = cnaLutFetch(ivec3(i0.x, i1.y, i1.z));
        return c000 + f.y * (c010 - c000) + f.z * (c011 - c010)
                    + f.x * (c111 - c011);
    }
    vec3 c010 = cnaLutFetch(ivec3(i0.x, i1.y, i0.z));
    vec3 c110 = cnaLutFetch(ivec3(i1.x, i1.y, i0.z));
    return c000 + f.y * (c010 - c000) + f.x * (c110 - c010)
                + f.z * (c111 - c110);
}

void main()
{
    vec4 source = texture(texture1, TexCoord);
    vec3 colour = clamp(source.rgb, 0.0, 1.0);
    vec3 graded = uColorGradeParams.z >= 0.5
                ? cnaLutTetrahedral(colour) : cnaLutTrilinear(colour);
    FragColor = vec4(mix(source.rgb, graded, uColorGradeParams.y), source.a) * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kDepthOfFieldDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core

in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;

uniform sampler2D texture1;
uniform sampler2D uDepthSampler;
uniform float uDofScalars[6];

const float kCnaSensorHeightMm = 24.0;
const vec2 kDisc[16] = vec2[16](
    vec2( 0.2165,  0.0745), vec2(-0.1863,  0.2549), vec2(-0.0851, -0.3777), vec2( 0.3966,  0.2154),
    vec2(-0.4644,  0.1509), vec2( 0.2260, -0.4707), vec2( 0.1751,  0.5411), vec2(-0.5527, -0.2338),
    vec2( 0.6033, -0.2467), vec2(-0.2249,  0.6414), vec2(-0.3225, -0.6321), vec2( 0.7108,  0.2116),
    vec2(-0.7357,  0.2420), vec2( 0.2941, -0.7628), vec2( 0.2497,  0.8004), vec2(-0.8098, -0.2646)
);

float cnaDecodeLinearDepth(vec4 channels)
{
    if (uDofScalars[5] < 0.5)
        return channels.r;
    const vec4 shift = vec4(1.0 / 16581375.0, 1.0 / 65025.0, 1.0 / 255.0, 1.0);
    return dot(channels, shift);
}

float cnaCircleOfConfusionMm(float depthWorld)
{
    float focusDistance = uDofScalars[1];
    float focalLength = uDofScalars[2];
    float fNumber = uDofScalars[3];
    if (depthWorld <= 0.0 || focusDistance <= 0.0 || fNumber <= 0.0)
        return 0.0;
    float focusMm = focusDistance * 1000.0;
    float depthMm = depthWorld * 1000.0;
    if (focusMm <= focalLength)
        return 0.0;
    return (focalLength * focalLength / (fNumber * (focusMm - focalLength)))
         * abs(depthMm - focusMm) / depthMm;
}

float cnaBlurRadius(float linearDepth)
{
    float diameterMm = cnaCircleOfConfusionMm(linearDepth * uDofScalars[0]);
    return min(0.5 * diameterMm / kCnaSensorHeightMm, uDofScalars[4]);
}

void main()
{
    vec3 centerColor = texture(texture1, TexCoord).rgb;
    float centerDepth = cnaDecodeLinearDepth(texture(uDepthSampler, TexCoord));
    if (centerDepth <= 0.0 || centerDepth >= 0.999)
    {
        FragColor = vec4(centerColor, 1.0) * SpriteColor;
        return;
    }

    float centerRadius = cnaBlurRadius(centerDepth);
    vec3 sum = centerColor;
    float weight = 1.0;
    for (int i = 0; i < 16; ++i)
    {
        vec2 offset = kDisc[i] * centerRadius;
        vec2 tapUv = TexCoord + offset;
        if (tapUv.x < 0.0 || tapUv.x > 1.0 || tapUv.y < 0.0 || tapUv.y > 1.0)
            continue;
        float tapDepth = cnaDecodeLinearDepth(texture(uDepthSampler, tapUv));
        if (tapDepth <= 0.0 || tapDepth >= 0.999)
            continue;
        float tapRadius = cnaBlurRadius(tapDepth);
        float accept = smoothstep(0.0, max(length(offset), 1e-5), tapRadius);
        sum += texture(texture1, tapUv).rgb * accept;
        weight += accept;
    }
    FragColor = vec4(sum / max(weight, 1e-5), 1.0) * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kFilmGrainDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core
in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;
uniform sampler2D texture1;
uniform vec4 uGrainParams;

float cnaHash(vec2 p)
{
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void main()
{
    vec4 source = texture(texture1, TexCoord);
    vec2 pixel = floor(TexCoord * uGrainParams.xy);
    float noise = cnaHash(pixel + vec2(uGrainParams.w * 71.0,
                                       uGrainParams.w * 113.0)) - 0.5;

    float luma = dot(source.rgb, vec3(0.299, 0.587, 0.114));
    float weight = 1.0 - abs(clamp(luma, 0.0, 1.0) * 2.0 - 1.0);

    FragColor = vec4(source.rgb + noise * uGrainParams.z * weight, source.a)
              * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kFxaaDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core
in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;
uniform sampler2D texture1;
uniform vec2 uTexelSize;
uniform float uEdgeThreshold;

float luma(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }

void main()
{
    vec3 center = texture(texture1, TexCoord).rgb;
    float lumaCenter = luma(center);
    float lumaNW = luma(texture(texture1, TexCoord + vec2(-uTexelSize.x, -uTexelSize.y)).rgb);
    float lumaNE = luma(texture(texture1, TexCoord + vec2( uTexelSize.x, -uTexelSize.y)).rgb);
    float lumaSW = luma(texture(texture1, TexCoord + vec2(-uTexelSize.x,  uTexelSize.y)).rgb);
    float lumaSE = luma(texture(texture1, TexCoord + vec2( uTexelSize.x,  uTexelSize.y)).rgb);

    float lumaMin = min(lumaCenter, min(min(lumaNW, lumaNE), min(lumaSW, lumaSE)));
    float lumaMax = max(lumaCenter, max(max(lumaNW, lumaNE), max(lumaSW, lumaSE)));

    if (lumaMax - lumaMin < uEdgeThreshold) {
        FragColor = vec4(center, 1.0);
        return;
    }

    vec2 direction = vec2(-((lumaNW + lumaNE) - (lumaSW + lumaSE)),
                           ((lumaNW + lumaSW) - (lumaNE + lumaSE)));
    float scale = 1.0 / (min(abs(direction.x), abs(direction.y)) + 0.125);
    direction = clamp(direction * scale, vec2(-8.0), vec2(8.0)) * uTexelSize;

    vec3 blended = 0.5 * (texture(texture1, TexCoord + direction * (1.0 / 3.0 - 0.5)).rgb +
                          texture(texture1, TexCoord + direction * (2.0 / 3.0 - 0.5)).rgb);
    vec3 wider = blended * 0.5 +
                 0.25 * (texture(texture1, TexCoord + direction * -0.5).rgb +
                         texture(texture1, TexCoord + direction *  0.5).rgb);

    float lumaWider = luma(wider);
    FragColor = vec4((lumaWider < lumaMin || lumaWider > lumaMax) ? blended : wider, 1.0)
              * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kHdrDisplayDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core
in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;
uniform sampler2D texture1;
uniform vec4 uHdrDisplayParams;

const float kM1 = 0.1593017578125;
const float kM2 = 78.84375;
const float kC1 = 0.8359375;
const float kC2 = 18.8515625;
const float kC3 = 18.6875;

vec3 cnaEncodePq(vec3 nits)
{
    vec3 l = clamp(nits / 10000.0, 0.0, 1.0);
    vec3 p = pow(l, vec3(kM1));
    return pow((kC1 + kC2 * p) / (1.0 + kC3 * p), vec3(kM2));
}

vec3 cnaRec709ToRec2020(vec3 c)
{
    return vec3(
        dot(c, vec3(0.6274039, 0.3292830, 0.0433131)),
        dot(c, vec3(0.0690973, 0.9195404, 0.0113623)),
        dot(c, vec3(0.0163914, 0.0880133, 0.8955953)));
}

float cnaRollOff(float nits, float peak)
{
    return nits <= 0.0 ? 0.0 : peak * nits / (peak + nits);
}

void main()
{
    int space = int(uHdrDisplayParams.x);
    vec4 source = texture(texture1, TexCoord);

    if (space == 0)
    {
        FragColor = source * SpriteColor;
        return;
    }

    if (space == 1)
    {
        FragColor = vec4(source.rgb * (uHdrDisplayParams.y / 80.0), source.a)
                  * SpriteColor;
        return;
    }

    vec3 nits = source.rgb * uHdrDisplayParams.y;
    nits = vec3(cnaRollOff(nits.r, uHdrDisplayParams.z),
                cnaRollOff(nits.g, uHdrDisplayParams.z),
                cnaRollOff(nits.b, uHdrDisplayParams.z));
    FragColor = vec4(cnaEncodePq(cnaRec709ToRec2020(nits)), source.a) * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kHeightFogDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core
in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;
uniform sampler2D texture1;
uniform sampler2D uDepthSampler;
uniform mat4 uFogMatrices[2];
uniform vec3 uFogVectors[1];
uniform float uFogScalars[5];

float cnaDecodeLinearDepth(vec4 channels)
{
    if (uFogScalars[4] < 0.5)
        return channels.r;
    const vec4 shift = vec4(1.0 / 16581375.0, 1.0 / 65025.0, 1.0 / 255.0, 1.0);
    return dot(channels, shift);
}

vec3 cnaViewPositionFromDepth(vec2 uv, float linearDepth)
{
    vec4 clip = vec4(uv * 2.0 - 1.0, 1.0, 1.0);
    vec4 ray = uFogMatrices[0] * clip;
    vec3 direction = ray.xyz / ray.w;
    return direction * (linearDepth / max(-direction.z, 1e-6));
}

float cnaOpticalDepth(float cameraHeight, float rayHeightStep, float distance)
{
    float atCamera = uFogScalars[1]
                   * exp(-uFogScalars[2] * (cameraHeight - uFogScalars[3]));
    float climb = uFogScalars[2] * rayHeightStep;
    if (abs(climb) < 1e-5)
        return max(atCamera * distance, 0.0);
    return max(atCamera * (1.0 - exp(-climb * distance)) / climb, 0.0);
}

void main()
{
    vec4 source = texture(texture1, TexCoord);
    float depth = cnaDecodeLinearDepth(texture(uDepthSampler, TexCoord));
    float farPlane = uFogScalars[0];
    float travelled = (depth <= 0.0 || depth >= 0.999) ? farPlane : depth * farPlane;
    vec3 viewPosition = cnaViewPositionFromDepth(TexCoord, max(depth, 1e-4)) * farPlane;
    vec4 world = uFogMatrices[1] * vec4(viewPosition, 1.0);
    vec4 cameraWorld = uFogMatrices[1] * vec4(0.0, 0.0, 0.0, 1.0);
    vec3 alongRay = world.xyz - cameraWorld.xyz;
    float rayLength = max(length(alongRay), 1e-4);
    float optical = cnaOpticalDepth(cameraWorld.y, alongRay.y / rayLength, travelled);
    float fog = 1.0 - exp(-optical);
    FragColor = vec4(mix(source.rgb, uFogVectors[0], clamp(fog, 0.0, 1.0)), source.a)
              * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kLensFlareDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core
in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;
uniform sampler2D texture1;
uniform vec4 uLensFlareParams;

vec3 cnaBright(vec2 uv)
{
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return vec3(0.0);
    return max(texture(texture1, uv).rgb - vec3(uLensFlareParams.x), vec3(0.0));
}

void main()
{
    vec4 source = texture(texture1, TexCoord);
    vec2 toCentre = vec2(0.5) - TexCoord;

    vec3 ghosts = vec3(0.0);
    for (int i = 1; i <= 8; ++i)
    {
        if (i > int(uLensFlareParams.w)) break;
        vec2 uv = TexCoord + toCentre * (1.0 + float(i) * uLensFlareParams.z);
        ghosts += cnaBright(uv) / float(i);
    }

    FragColor = vec4(source.rgb + ghosts * uLensFlareParams.y, source.a)
              * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kLightShaftDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core
in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;
uniform sampler2D texture1;
uniform vec4 uLightShaftParams;
uniform float uDecay;
uniform vec4 uRtFlipV;

const int kStepCount = 24;

vec3 cnaBright(vec2 uv)
{
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return vec3(0.0);
    return max(texture(texture1, uv).rgb - vec3(uLightShaftParams.z), vec3(0.0));
}

void main()
{
    vec4 source = texture(texture1, TexCoord);
    // SpriteBatch already mirrors the quad UVs for an OpenGL render-target source. Put the
    // screen-space light in that same sampled-texture coordinate system before walking to it.
    vec2 lightPosition = vec2(uLightShaftParams.x,
        mix(uLightShaftParams.y, 1.0 - uLightShaftParams.y, uRtFlipV.x));
    vec2 outside = max(vec2(0.0) - lightPosition, lightPosition - vec2(1.0));
    float offScreen = max(max(outside.x, outside.y), 0.0);
    float reach = clamp(1.0 - offScreen * 2.0, 0.0, 1.0);
    if (reach <= 0.0)
    {
        FragColor = source * SpriteColor;
        return;
    }

    vec2 step = (lightPosition - TexCoord) / float(kStepCount);
    vec3 gathered = vec3(0.0);
    float weight = 1.0;
    vec2 uv = TexCoord;
    for (int i = 0; i < kStepCount; ++i)
    {
        uv += step;
        gathered += cnaBright(uv) * weight;
        weight *= uDecay;
    }

    FragColor = vec4(source.rgb + gathered * (uLightShaftParams.w / float(kStepCount)) * reach,
                     source.a) * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kMotionBlurDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core

in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;

uniform sampler2D texture1;
uniform sampler2D uDepthSampler;
uniform sampler2D uVelocitySampler;
uniform mat4 uMotionMatrices[3];
uniform float uMotionScalars[6];

float cnaDecodeLinearDepth(vec4 channels)
{
    if (uMotionScalars[5] < 0.5)
        return channels.r;
    const vec4 shift = vec4(1.0 / 16581375.0, 1.0 / 65025.0, 1.0 / 255.0, 1.0);
    return dot(channels, shift);
}

vec2 cnaDecodeVelocity(vec4 channels)
{
    return (channels.xy - 0.5) * 2.0;
}

vec4 cnaGather(vec4 source, vec2 velocity, int sampleCount)
{
    float distance = length(velocity);
    if (distance > uMotionScalars[3])
        velocity *= uMotionScalars[3] / distance;

    vec3 sum = source.rgb;
    float weight = 1.0;
    for (int i = 1; i <= 16; ++i)
    {
        if (i >= sampleCount)
            break;
        vec2 uv = TexCoord - velocity * (float(i) / float(sampleCount - 1));
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0)
            continue;
        sum += texture(texture1, uv).rgb;
        weight += 1.0;
    }
    return vec4(sum / weight, source.a);
}

void main()
{
    vec4 source = texture(texture1, TexCoord);
    int sampleCount = int(uMotionScalars[4] + 0.5);

    if (uMotionScalars[0] > 0.5)
    {
        vec4 stored = texture(uVelocitySampler, TexCoord);
        if (stored.a < 0.5)
        {
            FragColor = cnaGather(source,
                                  cnaDecodeVelocity(stored) * uMotionScalars[2],
                                  sampleCount) * SpriteColor;
            return;
        }
    }

    float depth = cnaDecodeLinearDepth(texture(uDepthSampler, TexCoord));
    if (depth <= 0.0 || depth >= 0.999)
    {
        FragColor = source * SpriteColor;
        return;
    }

    vec4 clip = vec4(TexCoord * 2.0 - 1.0, 1.0, 1.0);
    vec4 ray = uMotionMatrices[0] * clip;
    vec3 direction = ray.xyz / ray.w;
    vec3 viewPosition = direction * (depth / max(-direction.z, 1e-6))
                      * uMotionScalars[1];
    vec4 world = uMotionMatrices[1] * vec4(viewPosition, 1.0);
    vec4 previousClip = uMotionMatrices[2] * world;
    if (previousClip.w <= 0.0)
    {
        FragColor = source * SpriteColor;
        return;
    }

    vec2 previousUv = (previousClip.xy / previousClip.w) * 0.5 + 0.5;
    vec2 velocity = (TexCoord - previousUv) * uMotionScalars[2];
    FragColor = cnaGather(source, velocity, sampleCount) * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kSpatialUpscaleDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core
in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;
uniform sampler2D texture1;
uniform vec4 uUpscaleParams;
uniform float uIdentity;

float cnaLuma(vec3 colour) { return dot(colour, vec3(0.2126, 0.7152, 0.0722)); }

vec3 cnaFetch(vec2 texel)
{
    vec2 sourceSize = uUpscaleParams.xy;
    return texture(texture1, clamp(texel, vec2(0.5), sourceSize - 0.5) / sourceSize).rgb;
}

void main()
{
    if (uIdentity > 0.5)
    {
        FragColor = texture(texture1, TexCoord) * SpriteColor;
        return;
    }

    vec2 position = TexCoord * uUpscaleParams.xy - 0.5;
    vec2 base = floor(position);
    vec2 f = position - base;

    vec3 c00 = cnaFetch(base + vec2(0.5, 0.5));
    vec3 c10 = cnaFetch(base + vec2(1.5, 0.5));
    vec3 c01 = cnaFetch(base + vec2(0.5, 1.5));
    vec3 c11 = cnaFetch(base + vec2(1.5, 1.5));
    vec3 upscaled = mix(mix(c00, c10, f.x), mix(c01, c11, f.x), f.y);

    if (uUpscaleParams.w > 0.5)
    {
        float l00 = cnaLuma(c00), l10 = cnaLuma(c10);
        float l01 = cnaLuma(c01), l11 = cnaLuma(c11);
        vec2 gradient = vec2((l10 + l11) - (l00 + l01),
                             (l01 + l11) - (l00 + l10));
        float strength = length(gradient);
        if (strength > 1e-4)
        {
            vec2 edge = normalize(vec2(-gradient.y, gradient.x));
            vec3 along = cnaFetch(base + vec2(0.5, 0.5) + f + edge)
                       + cnaFetch(base + vec2(0.5, 0.5) + f - edge);
            float trust = clamp(strength * 2.0, 0.0, 1.0) * 0.5;
            upscaled = mix(upscaled, along * 0.5, trust);
        }
    }

    if (uUpscaleParams.z > 0.0)
    {
        vec3 up = cnaFetch(base + vec2(0.5, -0.5));
        vec3 down = cnaFetch(base + vec2(0.5, 1.5));
        vec3 left = cnaFetch(base + vec2(-0.5, 0.5));
        vec3 right = cnaFetch(base + vec2(1.5, 0.5));
        vec3 neighbourhood = (up + down + left + right) * 0.25;
        vec3 sharpened = upscaled + (upscaled - neighbourhood) * uUpscaleParams.z;
        vec3 lowest = min(min(min(up, down), min(left, right)), upscaled);
        vec3 highest = max(max(max(up, down), max(left, right)), upscaled);
        upscaled = clamp(sharpened, lowest, highest);
    }

    FragColor = vec4(upscaled, 1.0) * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kSsaoComposeDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core

in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;

uniform sampler2D texture1;
uniform sampler2D uOcclusionSampler;
uniform vec2 uSsaoComposeVectors[1];
uniform float uSsaoComposeScalars[1];

void main()
{
    float blurred = 0.0;
    for (int y = -2; y <= 2; ++y)
    {
        for (int x = -2; x <= 2; ++x)
        {
            blurred += texture(
                uOcclusionSampler,
                TexCoord + vec2(float(x), float(y)) * uSsaoComposeVectors[0]).r;
        }
    }
    blurred /= 25.0;

    float visibility = clamp(
        1.0 - (1.0 - blurred) * uSsaoComposeScalars[0], 0.0, 1.0);
    vec4 scene = texture(texture1, TexCoord);
    FragColor = vec4(scene.rgb * visibility, scene.a) * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kSsaoOcclusionDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core

in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;

uniform sampler2D texture1;
uniform sampler2D uNormalSampler;
uniform sampler2D uNoiseSampler;
uniform vec3 uSsaoKernel[64];
uniform vec2 uSsaoVectors[1];
uniform float uSsaoScalars[5];

float cnaDecodeLinearDepth(vec4 channels)
{
    if (uSsaoScalars[4] < 0.5)
        return channels.r;
    const vec4 shift = vec4(1.0 / 16581375.0, 1.0 / 65025.0, 1.0 / 255.0, 1.0);
    return dot(channels, shift);
}

void main()
{
    float centerDepth = cnaDecodeLinearDepth(texture(texture1, TexCoord));
    if (centerDepth <= 0.0) {
        FragColor = vec4(1.0, 1.0, 1.0, 1.0);
        return;
    }

    vec3 rawNormal = texture(uNormalSampler, TexCoord).xyz * 2.0 - 1.0;
    vec3 normal = length(rawNormal) > 1e-4 ? normalize(rawNormal) : vec3(0.0, 0.0, 1.0);

    vec3 rawRandom = vec3(texture(uNoiseSampler, TexCoord * uSsaoVectors[0]).xy * 2.0 - 1.0,
                          0.0);
    vec3 randomVector = length(rawRandom) > 1e-4
                      ? normalize(rawRandom)
                      : vec3(1.0, 0.0, 0.0);

    vec3 rawTangent = randomVector - normal * dot(randomVector, normal);
    vec3 tangent = length(rawTangent) > 1e-4
                 ? normalize(rawTangent)
                 : normalize(cross(normal, vec3(0.0, 1.0, 0.0)) + vec3(1e-3, 0.0, 0.0));
    vec3 bitangent = cross(normal, tangent);
    mat3 tbn = mat3(tangent, bitangent, normal);

    float occlusion = 0.0;
    int count = int(uSsaoScalars[3] + 0.5);
    for (int i = 0; i < 64; ++i)
    {
        if (i >= count)
            break;

        vec3 samplePosition = tbn * uSsaoKernel[i];
        vec2 sampleUv = TexCoord + samplePosition.xy * uSsaoScalars[0];
        float sampleDepth = cnaDecodeLinearDepth(textureLod(texture1, sampleUv, 0.0));
        if (sampleDepth <= 0.0)
            continue;

        if (sampleDepth < centerDepth - uSsaoScalars[1])
        {
            float rangeCheck = smoothstep(
                0.0, 1.0,
                uSsaoScalars[2] / max(abs(centerDepth - sampleDepth), 1e-5));
            occlusion += rangeCheck;
        }
    }

    float visibility = 1.0 - occlusion / float(count);
    FragColor = vec4(visibility, visibility, visibility, 1.0) * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kSsrDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core

in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;

uniform sampler2D texture1;
uniform sampler2D uDepthSampler;
uniform sampler2D uNormalSampler;
uniform vec2 uSsrVectors[1];
uniform mat4 uSsrMatrices[2];
uniform float uSsrScalars[9];

const float kCnaSkyDepth = 0.999;
const int kCnaRefineSteps = 6;

float cnaDecodeLinearDepth(vec4 channels)
{
    if (uSsrScalars[8] < 0.5)
        return channels.r;
    const vec4 shift = vec4(1.0 / 16581375.0, 1.0 / 65025.0, 1.0 / 255.0, 1.0);
    return dot(channels, shift);
}

vec3 cnaViewPositionFromDepth(vec2 uv, float linearDepth)
{
    vec4 clip = vec4(uv * 2.0 - 1.0, 1.0, 1.0);
    vec4 ray = uSsrMatrices[1] * clip;
    vec3 direction = ray.xyz / ray.w;
    return direction * (linearDepth / max(-direction.z, 1e-6));
}

vec2 cnaSnapToTexel(vec2 uv)
{
    return (floor(uv * uSsrVectors[0]) + 0.5) / uSsrVectors[0];
}

void main()
{
    vec3 sourceColor = texture(texture1, TexCoord).rgb;
    float centerDepth = cnaDecodeLinearDepth(
        texture(uDepthSampler, cnaSnapToTexel(TexCoord)));
    if (centerDepth <= 0.0 || centerDepth >= kCnaSkyDepth)
    {
        FragColor = vec4(sourceColor, 1.0) * SpriteColor;
        return;
    }

    vec4 normalTexel = texture(uNormalSampler, cnaSnapToTexel(TexCoord));
    float roughness = clamp(normalTexel.a, 0.0, 1.0);
    vec3 rawNormal = normalTexel.xyz * 2.0 - 1.0;
    vec3 normal = length(rawNormal) > 1e-4
                ? normalize(rawNormal) : vec3(0.0, 0.0, 1.0);

    vec3 position = cnaViewPositionFromDepth(TexCoord, centerDepth);
    vec3 incident = length(position) > 1e-6
                  ? normalize(position) : vec3(0.0, 0.0, -1.0);
    vec3 reflected = normalize(reflect(incident, normal));
    float stepLength = uSsrScalars[1] / uSsrScalars[7];
    vec3 hitColor = vec3(0.0);
    float hit = 0.0;
    vec3 lastClear = position;

    for (int i = 1; i <= 64; ++i)
    {
        if (float(i) > uSsrScalars[7])
            break;
        vec3 samplePosition = position + reflected * (stepLength * float(i));
        if (samplePosition.z >= -1e-6)
            break;

        vec4 clip = uSsrMatrices[0]
                  * vec4(samplePosition * uSsrScalars[0], 1.0);
        if (clip.w <= 0.0)
            break;
        vec2 sampleUv = (clip.xy / clip.w) * 0.5 + 0.5;
        if (sampleUv.x < 0.0 || sampleUv.x > 1.0 ||
            sampleUv.y < 0.0 || sampleUv.y > 1.0)
            break;

        vec2 snappedUv = cnaSnapToTexel(sampleUv);
        float sceneDepth = cnaDecodeLinearDepth(textureLod(uDepthSampler, snappedUv, 0.0));
        if (sceneDepth <= 0.0 || sceneDepth >= kCnaSkyDepth)
            continue;

        float difference = -samplePosition.z - sceneDepth;
        if (difference > uSsrScalars[2] && difference < uSsrScalars[3])
        {
            vec3 nearPoint = lastClear;
            vec3 farPoint = samplePosition;
            for (int k = 0; k < kCnaRefineSteps; ++k)
            {
                vec3 middle = (nearPoint + farPoint) * 0.5;
                vec4 middleClip = uSsrMatrices[0]
                                * vec4(middle * uSsrScalars[0], 1.0);
                if (middleClip.w <= 0.0)
                    break;
                vec2 middleUv = cnaSnapToTexel(
                    (middleClip.xy / middleClip.w) * 0.5 + 0.5);
                float middleDepth = cnaDecodeLinearDepth(
                    textureLod(uDepthSampler, middleUv, 0.0));
                bool behind = middleDepth > 0.0 && middleDepth < kCnaSkyDepth &&
                              (-middle.z - middleDepth) > uSsrScalars[2];
                if (behind)
                    farPoint = middle;
                else
                    nearPoint = middle;
            }

            vec4 hitClip = uSsrMatrices[0]
                         * vec4(farPoint * uSsrScalars[0], 1.0);
            vec2 hitUv = cnaSnapToTexel((hitClip.xy / hitClip.w) * 0.5 + 0.5);
            vec3 rawHitNormal = texture(uNormalSampler, hitUv).xyz * 2.0 - 1.0;
            vec3 hitNormal = length(rawHitNormal) > 1e-4
                           ? normalize(rawHitNormal) : vec3(0.0, 0.0, 1.0);
            if (dot(reflected, hitNormal) > 0.0)
                break;

            vec2 toEdge = min(hitUv, vec2(1.0) - hitUv);
            float fade = uSsrScalars[5] > 0.0
                ? min(smoothstep(0.0, uSsrScalars[5], toEdge.x),
                      smoothstep(0.0, uSsrScalars[5], toEdge.y))
                : 1.0;
            vec2 blur = vec2(roughness * uSsrScalars[6]);
            vec3 gathered = texture(texture1, hitUv).rgb
                          + texture(texture1, hitUv + vec2( blur.x, 0.0)).rgb
                          + texture(texture1, hitUv + vec2(-blur.x, 0.0)).rgb
                          + texture(texture1, hitUv + vec2(0.0,  blur.y)).rgb
                          + texture(texture1, hitUv + vec2(0.0, -blur.y)).rgb;
            hitColor = gathered * 0.2;
            hit = fade;
            break;
        }

        lastClear = samplePosition;
    }

    FragColor = vec4(mix(sourceColor, hitColor, hit * uSsrScalars[4]), 1.0)
              * SpriteColor;
}
)CNA_SHADER";

inline constexpr std::string_view kTonemapDesktopFragmentSource =
    R"CNA_SHADER(#version 330 core
in vec2 TexCoord;
in vec4 SpriteColor;
out vec4 FragColor;
uniform sampler2D texture1;
uniform vec4 uTonemapParams;

vec3 reinhard(vec3 c) { return c / (1.0 + c); }

vec3 filmic(vec3 c)
{
    vec3 x = max(vec3(0.0), c - 0.004);
    return (x * (6.2 * x + 0.5)) / (x * (6.2 * x + 1.7) + 0.06);
}

vec3 aces(vec3 c)
{
    const float a = 2.51, b = 0.03, cc = 2.43, d = 0.59, e = 0.14;
    return clamp((c * (a * c + b)) / (c * (cc * c + d) + e), 0.0, 1.0);
}

vec3 uncharted2Curve(vec3 x)
{
    const float A = 0.15, B = 0.50, C = 0.10, D = 0.20, E = 0.02, F = 0.30;
    return ((x * (A * x + C * B) + D * E) / (x * (A * x + B) + D * F)) - E / F;
}

vec3 uncharted2(vec3 c)
{
    const float W = 11.2;
    return uncharted2Curve(c) / uncharted2Curve(vec3(W));
}

float cnaDitherHash(vec2 position)
{
    return fract(sin(dot(position, vec2(12.9898, 78.233))) * 43758.5453);
}

float cnaTriangularDither(vec2 position)
{
    return cnaDitherHash(position) - cnaDitherHash(position + vec2(17.0, 23.0));
}

void main()
{
    int mode = int(uTonemapParams.x);
    vec4 source = texture(texture1, TexCoord);
    vec3 color = source.rgb * uTonemapParams.y;

    if (mode == 1)      color = reinhard(color);
    else if (mode == 2) color = filmic(color);
    else if (mode == 3) color = aces(color);
    else if (mode == 4) color = uncharted2(color);

    color = clamp(color, 0.0, 1.0);
    if (mode != 2) color = pow(color, vec3(uTonemapParams.z));
    if (uTonemapParams.w > 0.0)
        color += vec3(cnaTriangularDither(gl_FragCoord.xy) * uTonemapParams.w);

    FragColor = vec4(color, source.a) * SpriteColor;
}
)CNA_SHADER";

